from pathlib import Path
import re
R=Path('research/quantum-build-60-2026-10-15-owner/complex')
def patch(id,deps,fn):
 p=Path('items')/(id+'.md');s=p.read_text();(R/'before'/p.name).write_bytes(p.read_bytes());s=re.sub(r'verification:\n.*?(?=^sources:)', '', s, flags=re.M|re.S);s=s.replace('deps: [','deps: ['+', '.join(deps)+', ');(R/'items'/p.name).write_text(fn(s))
patch('thm-riemann-stieltjes-and-parametric-contour-integrals-agree',['thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed','def-absolute-line-integral-over-a-rectifiable-path'],lambda s:s.replace('**Given:** A piecewise-$C^1$ contour $\\gamma=x+iy$, a continuous $f=u+iv$, and an admissible partition $(t_j)$.','**Given:** A piecewise-$C^1$ contour $\\gamma=x+iy$, a continuous $f=u+iv$, and an admissible partition $(t_j)$. Apply all Euclidean path suppliers below to $\\Gamma=\\Phi\\circ\\gamma=(x,y)$. By [[thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed]], complex length agrees with coordinate length on every subinterval, the complex velocity notation is $\\gamma\'_j=x\'_j+iy\'_j$, and $|\\gamma\'_j|=\\|\\Gamma\'_j\\|_2$. The absolute-integral definition [[def-absolute-line-integral-over-a-rectifiable-path]] gives $s_\\gamma=s_\\Gamma$; on each smooth piece this differs from its local arc-length function by a constant. In [L2] use the real vector fields $(u\\circ\\Phi^{-1},-v\\circ\\Phi^{-1})$ and $(v\\circ\\Phi^{-1},u\\circ\\Phi^{-1})$ along $\\Gamma$, and the analogous scalar field.'))
patch('thm-invariance-of-complex-line-integrals-under-increasing-reparametrization',['thm-complex-path-length-invariant-under-monotone-reparametrization'],lambda s:s.replace('Arc length is invariant under continuous surjective monotone reparametrization, including the stated singleton cases ([[thm-arc-length-is-invariant-under-monotone-reparametrization]]).','Complex arc length is invariant under continuous surjective monotone reparametrization, including singleton cases ([[thm-complex-path-length-invariant-under-monotone-reparametrization]]), by coordinate transport of [[thm-arc-length-is-invariant-under-monotone-reparametrization]]. Applied to every restriction this gives $s_{\\gamma\\circ\\phi}(t)=s_\\gamma(\\phi(t))$.').replace('On piecewise-$C^1$ contours this is exactly the increasing half of [L3]','On piecewise-$C^1$ contours apply [L3] to the coordinate path and coordinate vector fields; it gives exactly the increasing identity'))
patch('thm-fundamental-inequality-for-complex-line-integrals',['thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed','def-absolute-line-integral-over-a-rectifiable-path'],lambda s:s.replace('Every chord of a rectifiable path is at most the length of the corresponding subpath ([[cor-chord-length-is-at-most-arc-length]]).','Apply [[cor-chord-length-is-at-most-arc-length]] to $\\Gamma=\\Phi\\circ\\gamma$. Chord and subpath lengths equal the complex lengths by [[thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed]]. With $s_\\gamma=s_\\Gamma$ as in [[def-absolute-line-integral-over-a-rectifiable-path]], the chord bound is therefore $|\\gamma(v)-\\gamma(u)|\\le s_\\gamma(v)-s_\\gamma(u)$.'))
patch('thm-fundamental-theorem-for-complex-line-integrals',['thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed','thm-complex-coordinate-isometry-and-topology-transport','thm-riemann-stieltjes-and-parametric-contour-integrals-agree'],lambda s:s.replace('**Given:** A rectifiable contour $\\gamma$ and a primitive $F$ with continuous derivative $f$.','**Given:** A rectifiable contour $\\gamma$ and a primitive $F$ with continuous derivative $f$. All Euclidean path statements [L2] and [L9] apply to $\\Phi\\circ\\gamma$; [[thm-complex-path-coordinate-length-rectifiability-and-piecewise-c1-speed]] transfers their chord and subpath-length assertions to $\\gamma$. Open balls and segments transfer by [[thm-complex-coordinate-isometry-and-topology-transport]]. In [L4] use the coordinate straight segment and the real and imaginary components of $F\\circ\\Phi^{-1}$. Their vector-integral endpoint identities recombine into the complex segment integral by [[thm-riemann-stieltjes-and-parametric-contour-integrals-agree]].'))
patch('thm-morera-triangle-theorem',['def-star-shaped-open-subset-of-rn','thm-complex-coordinate-isometry-and-topology-transport'],lambda s:s.replace('the disc $D(a,r)$ is star-shaped with respect to $a$,','the disc $D(a,r)$ is open and contains $a$. For $z$ in it and $0\\le t\\le1$, $|a+t(z-a)-a|=t|z-a|<r$; openness and segment transport in [[thm-complex-coordinate-isometry-and-topology-transport]] show its coordinate image is star-shaped at $\\Phi(a)$ in [[def-star-shaped-open-subset-of-rn]],'))
